import React, { useState } from 'react'


//Displays all the tasks
const test = (TodoArrayItem) => {
  toggleCompleted(TodoArrayItem.id)
}
const ToDoItem = (TodoArrayItem, toggleCompleted, deleteTodo) => {
  return (
    <div>
      <li>
      {/* main content */}
      {TodoArrayItem.text} &nbsp; &nbsp;
      {TodoArrayItem.timestamp}
      {/* complete buttton */}
      <button onClick={() => test(TodoArrayItem)}>
        {/* function to determine if we should write undo or complete in the button */}
        {()=>{
          if(TodoArrayItem.completed){
            return("Undo")
          }
          else{
            return("Complete")
          }
        }}
        {/* delete button */}
      </button>
      <button onClick={() => deleteTodo(TodoArrayItem.id)}>Delete</button>
      </li>
    </div>
  )
}

export default ToDoItem
